};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_isurCd kisComCd ipt_repIsuSrtCd comNm ipt_comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (ipt_isurCd, kisComCd, ipt_repIsuSrtCd, comNm, ipt_comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let str = "";
    str += "isurCd : " + ipt_isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + ipt_comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent('AKCKwd').setValue(ipt_comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "A" + ipt_repIsuSrtCd);
    $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "char");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnBtnType
 * @author Inswave
 * @date 2026. 09. 29
 * @param type idx
 * @returns
 * @hidden N
*/
scwin.fnBtnType = async function (type, idx) {
    /* sdd-asis-lifecycle:begin fnBtnType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.fnClearBtnType();
    scwin.fnClearCorpName();
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("beginIndex", type);
    $(document).find("a[id=btnType]").each(function(index) {
            if (idx === index) {
                if (!$(this).hasClass("active")) {
                    $(this).addClass("active");
                }
            }
    });
    await scwin.fnInit();
    /* sdd-asis-lifecycle:end */
};
